import sys
import xml.etree.ElementTree as ET
import operator

def evaluate_expression(expr):
    tokens = []
    i = 0
    while i < len(expr):
        if expr[i] == ' ':
            i += 1
            continue
        if expr[i] in '+-*/()':
            tokens.append(expr[i])
            i += 1
        else:
            num = ''
            while i < len(expr) and expr[i].isdigit():
                num += expr[i]
                i += 1
            tokens.append(num)
    # Convert tokens to numbers and operators
    stack = []
    precedence = {'+': 1, '-': 1, '*': 2, '(': 0}
    for token in tokens:
        if token == '(':
            stack.append(token)
        elif token == ')':
            while stack and stack[-1] != '(':
                stack.append(operator.__add__ if stack.pop() == '+' else operator.__sub__ if stack.pop() == '-' else operator.__mul__)
            stack.pop()  # Remove '('
        elif token in '+-*/':
            while stack and stack[-1] != '(' and precedence.get(stack[-1], 0) >= precedence.get(token, 0):
                stack.append(operator.__add__ if token == '+' else operator.__sub__ if token == '-' else operator.__mul__)
                stack.pop()
            stack.append(token)
        else:
            stack.append(int(token))
    # Evaluate the stack
    result = stack[0]
    for i in range(1, len(stack), 2):
        op = stack[i]
        num = stack[i+1]
        if op == operator.__add__:
            result += num
        elif op == operator.__sub__:
            result -= num
        elif op == operator.__mul__:
            result *= num
    return result

