import sys
import xml.etree.ElementTree as ET
import operator

def evaluate_expression(expr):
    tokens = expr.split()
    stack = []
    ops = []
    precedence = {'+': 1, '-': 1, '*': 2, '(': 0}

    for token in tokens:
        if token.isdigit():
            stack.append(int(token))
        elif token == '(':
            ops.append(token)
        elif token == ')':
            while ops and ops[-1] != '(':
                stack.append(ops.pop())
            ops.pop()  # Remove the '('
        else:
            while ops and precedence[ops[-1]] >= precedence[token]:
                stack.append(ops.pop())
            ops.append(token)

    while ops:
        stack.append(ops.pop())

    result = stack[0]
    for i in range(1, len(stack), 2):
        op = stack[i]
        val = stack[i+1]
        if op == '+':
            result += val
        elif op == '-':
            result -= val
        elif op == '*':
            result *= val

    return result

def main():
    xml_path = sys.argv[1]
    token = sys.argv[2]

    tree = ET.parse(xml_path)
    root = tree.getroot()

    for job in root.findall('job'):
        if job.get('token') == token:
            expr = job.text
            result = evaluate_expression(expr)
            print(f"{job.get('id')}={result}")

if __name__ == "__main__":
